"description": "绘制左侧防滑垫凹槽 (24mm x 10mm)",
"params": {
"x1": -0.045,
"y1": -0.035,
"z1": 0.0,
"x2": -0.021,
"y2": -0.025,
"z2": 0.0
}
},
{
"operation": "feature_cut_extrusion",
