{
  "user_intent": "创建一个一体式桌面手机支架，包含底座、74°倾斜背板、前端挡唇、两侧三角加强筋、背部 U 形充电槽、三个散热槽以及底面防滑垫凹槽，最后进行圆角处理。",
  "steps": [
    {
      "operation": "new_part",
      "params": {},
      "description": "新建零件文档"
    },
    {
      "operation": "select_plane",
      "params": {
        "index": 1
      },
      "description": "选择上视基准面（Top Plane）绘制底座和挡唇的轮廓草图"
    },
    {
      "operation": "sketch_rectangle",
      "params": {
        "x1": -0.055,
        "y1": -0.039,
        "x2": 0.055,
        "y2": 0.039
      },
      "description": "绘制底座外轮廓矩形 (110mm x 78mm)，中心在原点"
    },
    {
      "operation": "sketch_rectangle",
      "params": {
        "x1": -0.055,
        "y1": -0.039,
        "x2": -0.045,
        "y2": 0.039
      },
      "description": "绘制前端挡唇轮廓矩形 (宽 10mm, 长 78mm)，位于底座最前端"
    },
    {
      "operation": "feature_extrusion",
      "params": {
        "depth": 0.008,
        "midPlane": false
      },
      "description": "拉伸底座主体 8mm 高度"
    },
    {
      "operation": "select_face_and_sketch",
      "params": {
        "rx": 0.0,
        "ry": 0.01,
        "rz": -0.045,
        "dx": 0.0,
        "dy": -1.0,
        "dz": 0.0
      },
      "description": "选中挡唇顶面，准备绘制挡唇加高部分"
    },
    {
      "operation": "sketch_rectangle",
      "params": {
        "x1": -0.055,
        "y1": -0.039,
        "x2": -0.045,
        "y2": 0.039
      },
      "description": "在挡唇顶面绘制相同轮廓以加高"
    },
    {
      "operation": "feature_extrusion",
      "params": {
        "depth": 0.012,
        "midPlane": false
      },
      "description": "将挡唇向上拉伸 12mm，使总高度达到 20mm"
