    {
      "operation": "select_plane",
      "params": {
        "index": 2
      },
      "description": "选择右视基准面（Right Plane）绘制背板和加强筋的侧面轮廓"
    },
    {
      "operation": "sketch_line",
      "params": {
        "x1": -0.045,
        "y1": 0.008,
        "x2": -0.045,
        "y2": 0.0
      },
      "description": "绘制背板底部垂直线（从底座后缘上表面向下到基准）"
    },
    {
      "operation": "sketch_line",
      "params": {
        "x1": -0.045,
        "y1": 0.0,
        "x2": 0.0366,
        "y2": 0.11
      },
      "description": "绘制背板倾斜底线 (74°倾角，长度约 118/sin(74)≈122.8mm 投影)"
