    {
      "operation": "sketch_line",
      "params": {
        "x1": 0.0366,
        "y1": 0.11,
        "x2": 0.0366,
        "y2": 0.116
      },
      "description": "绘制背板顶部垂直线 (厚度 6mm 的水平投影修正)"
