    {
      "operation": "sketch_line",
      "params": {
        "x1": 0.0366,
        "y1": 0.116,
        "x2": -0.045,
        "y2": 0.014
      },
      "description": "绘制背板倾斜顶线"
    },
    {
      "operation": "sketch_line",
      "params": {
        "x1": -0.045,
        "y1": 0.014,
        "x2": -0.045,
        "y2": 0.008
      },
      "description": "闭合背板轮廓左侧"
    },
    {
      "operation": "sketch_line",
      "params": {
        "x1": -0.045,
        "y1": 0.008,
        "x2": -0.025,
        "y2": 0.008
      },
      "description": "绘制加强筋底部水平线"
    },
    {
      "operation": "sketch_line",
      "params": {
        "x1": -0.025,
        "y1": 0.008,
        "x2": 0.01,
        "y2": 0.06
      },
      "description": "绘制加强筋斜边"
    },
    {
      "operation": "sketch_line",
      "params": {
        "x1": 0.01,
        "y1": 0.06,
        "x2": -0.045,
        "y2": 0.014
      },
      "description": "连接加强筋顶点到背板内侧"
